@using sv_39528750ee8f4288b8607abe9ca45809.Services
@inject ISettingsService SettingsService

<div class="settings-section">
    <h2>Security Settings</h2>

    @if (_loading)
    {
        <p class="loading">Loading security settings...</p>
    }
    else
    {
        <div class="security-form">
            <!-- Change Password Panel -->
            <div class="expandable-panel">
                <button class="panel-header" @onclick="() => _passwordPanelOpen = !_passwordPanelOpen">
                    <span>Change Password</span>
                    <span class="expand-icon">@(_passwordPanelOpen ? "▾" : "▸")</span>
                </button>
                @if (_passwordPanelOpen)
                {
                    <div class="panel-body">
                        <div class="form-group">
                            <label for="currentPassword">Current Password</label>
                            <input id="currentPassword" type="password" @bind="_currentPassword" />
                        </div>
                        <div class="form-group">
                            <label for="newPassword">New Password</label>
                            <input id="newPassword" type="password" @bind="_newPassword" />
                        </div>
                        <div class="form-group">
                            <label for="confirmPassword">Confirm Password</label>
                            <input id="confirmPassword" type="password" @bind="_confirmPassword" />
                        </div>
                        <button class="btn btn-primary" @onclick="ChangePasswordAsync">Update Password</button>

                        @if (!string.IsNullOrEmpty(_passwordMessage))
                        {
                            <div class="toast @(_passwordError ? "toast-error" : "toast-success")">@_passwordMessage</div>
                        }
                    </div>
                }
            </div>

            <!-- Two-Factor Authentication -->
            <div class="twofa-section">
                <div class="twofa-row">
                    <div>
                        <h3>Two-Factor Authentication</h3>
                        <span class="status-indicator @(_twoFactorEnabled ? "status-enabled" : "status-disabled")">
                            @(_twoFactorEnabled ? "Enabled" : "Disabled")
                        </span>
                    </div>
                    <label class="toggle-label">
                        <input type="checkbox" @bind="_twoFactorEnabled" class="toggle-input" />
                        <span class="toggle-switch"></span>
                    </label>
                </div>
                @if (_lastPasswordChange.HasValue)
                {
                    <p class="last-changed">Last password change: @_lastPasswordChange.Value.ToString("MMMM dd, yyyy")</p>
                }
            </div>

            <!-- Active Sessions -->
            <ActiveSessionsTable Sessions="_sessions"
                                 CurrentSessionId="@_currentSessionId"
                                 OnRevoke="RevokeSessionAsync" />

            @if (!string.IsNullOrEmpty(_message))
            {
                <div class="toast @(_isError ? "toast-error" : "toast-success")">@_message</div>
            }
        </div>
    }
</div>

@code {
    private bool _loading = true;
    private bool _passwordPanelOpen;
    private bool _twoFactorEnabled;
    private DateTime? _lastPasswordChange;
    private List<ActiveSession> _sessions = new();
    private string _currentSessionId = "";

    private string _currentPassword = "";
    private string _newPassword = "";
    private string _confirmPassword = "";
    private string? _passwordMessage;
    private bool _passwordError;
    private string? _message;
    private bool _isError;

    protected override async Task OnInitializedAsync()
    {
        _loading = true;
        var settings = await SettingsService.GetSecuritySettingsAsync();
        _twoFactorEnabled = settings.TwoFactorEnabled;
        _lastPasswordChange = settings.LastPasswordChange;
        _sessions = settings.Sessions;
        // First session is treated as "current"
        _currentSessionId = _sessions.FirstOrDefault()?.Id ?? "";
        _loading = false;
    }

    private async Task ChangePasswordAsync()
    {
        if (string.IsNullOrWhiteSpace(_newPassword))
        {
            _passwordMessage = "New password cannot be empty.";
            _passwordError = true;
            return;
        }

        if (_newPassword != _confirmPassword)
        {
            _passwordMessage = "Passwords do not match.";
            _passwordError = true;
            return;
        }

        try
        {
            await SettingsService.ChangePasswordAsync(_currentPassword, _newPassword);
            _passwordMessage = "Password updated successfully!";
            _passwordError = false;
            _currentPassword = "";
            _newPassword = "";
            _confirmPassword = "";
        }
        catch (Exception ex)
        {
            _passwordMessage = $"Error: {ex.Message}";
            _passwordError = true;
        }
        _ = ClearPasswordMessageAfterDelay();
    }

    private async Task RevokeSessionAsync(string sessionId)
    {
        try
        {
            await SettingsService.RevokeSessionAsync(sessionId);
            _sessions = _sessions.Where(s => s.Id != sessionId).ToList();
            _message = "Session revoked.";
            _isError = false;
        }
        catch (Exception ex)
        {
            _message = $"Error: {ex.Message}";
            _isError = true;
        }
        _ = ClearMessageAfterDelay();
    }

    private async Task ClearPasswordMessageAfterDelay()
    {
        await Task.Delay(3000);
        _passwordMessage = null;
        await InvokeAsync(StateHasChanged);
    }

    private async Task ClearMessageAfterDelay()
    {
        await Task.Delay(3000);
        _message = null;
        await InvokeAsync(StateHasChanged);
    }
}
"}

