@namespace sv_39528750ee8f4288b8607abe9ca45809.Components.Pages.Settings
@using sv_39528750ee8f4288b8607abe9ca45809.Services

<div class="sessions-section">
    <h3>Active Sessions</h3>
    <table class="sessions-table">
        <thead>
            <tr>
                <th>Device</th>
                <th>Location</th>
                <th>Last Active</th>
                <th>Action</th>
            </tr>
        </thead>
        <tbody>
            @foreach (var session in Sessions)
            {
                <tr>
                    <td>@session.Device</td>
                    <td>@session.Location</td>
                    <td>@session.LastActive.ToString("g")</td>
                    <td>
                        @if (session.Id != CurrentSessionId)
                        {
                            @if (_confirmingSessionId == session.Id)
                            {
                                <span class="confirm-revoke">
                                    <span>Revoke?</span>
                                    <button class="btn btn-danger btn-sm" @onclick="() => ConfirmRevoke(session.Id)">Yes</button>
                                    <button class="btn btn-secondary btn-sm" @onclick="CancelRevoke">No</button>
                                </span>
                            }
                            else
                            {
                                <button class="btn btn-warning btn-sm" @onclick="() => RequestRevoke(session.Id)">Revoke</button>
                            }
                        }
                        else
                        {
                            <span class="current-session-badge">Current</span>
                        }
                    </td>
                </tr>
            }
        </tbody>
    </table>
</div>

@code {
    [Parameter] public List<ActiveSession> Sessions { get; set; } = new();
    [Parameter] public string CurrentSessionId { get; set; } = "";
    [Parameter] public EventCallback<string> OnRevoke { get; set; }

    private string? _confirmingSessionId;

    private void RequestRevoke(string sessionId)
    {
        _confirmingSessionId = sessionId;
    }

    private void CancelRevoke()
    {
        _confirmingSessionId = null;
    }

    private async Task ConfirmRevoke(string sessionId)
    {
        _confirmingSessionId = null;
        await OnRevoke.InvokeAsync(sessionId);
    }
}

