namespace sv_39528750ee8f4288b8607abe9ca45809.Services;

/// <summary>
/// In-memory implementation for demonstration purposes.
/// </summary>
public class InMemorySettingsService : ISettingsService
{
    private UserProfile _profile = new("Jane Doe", "jane@example.com", "https://i.pravatar.cc/150?img=5", "Software engineer who loves building great products.");
    private NotificationPrefs _notifications = new(true, true, false, new List<string> { "Random" });
    private SecuritySettings _security = new(true, DateTime.Now.AddDays(-30), new List<ActiveSession>
    {
        new("sess-1", "Chrome on Windows", "New York, US", DateTime.Now.AddMinutes(-5)),
        new("sess-2", "Safari on iPhone", "San Francisco, US", DateTime.Now.AddHours(-2)),
        new("sess-3", "Firefox on Linux", "London, UK", DateTime.Now.AddDays(-1)),
    });
    private AppearanceSettings _appearance = new("System", "Medium", "English", false);

    public Task<UserProfile> GetProfileAsync() => Task.FromResult(_profile);

    public Task SaveProfileAsync(UserProfile profile)
    {
        _profile = profile;
        return Task.CompletedTask;
    }

    public Task<NotificationPrefs> GetNotificationPrefsAsync() => Task.FromResult(_notifications);

    public Task SaveNotificationPrefsAsync(NotificationPrefs prefs)
    {
        _notifications = prefs;
        return Task.CompletedTask;
    }

    public Task<SecuritySettings> GetSecuritySettingsAsync() => Task.FromResult(_security);

    public Task ChangePasswordAsync(string currentPassword, string newPassword)
    {
        if (string.IsNullOrWhiteSpace(currentPassword))
            throw new InvalidOperationException("Current password is required.");

        _security = _security with { LastPasswordChange = DateTime.Now };
        return Task.CompletedTask;
    }

    public Task RevokeSessionAsync(string sessionId)
    {
        _security = _security with
        {
            Sessions = _security.Sessions.Where(s => s.Id != sessionId).ToList()
        };
        return Task.CompletedTask;
    }

    public Task<AppearanceSettings> GetAppearanceAsync() => Task.FromResult(_appearance);

    public Task SaveAppearanceAsync(AppearanceSettings settings)
    {
        _appearance = settings;
        return Task.CompletedTask;
    }
}

