+    font-size: 0.9rem;
+    animation: slideIn 0.3s ease;
+}
+
+.toast-success {
+    background: #d1e7dd;
+    color: #0f5132;
+    border: 1px solid #badbcc;
+}
+
+.toast-error {
+    background: #f8d7da;
+    color: #842029;
+    border: 1px solid #f5c2c7;
+}
+
+@keyframes slideIn {
+    from { opacity: 0; transform: translateY(-8px); }
+    to { opacity: 1; transform: translateY(0); }
+}
+
+/* ===== Avatar ===== */
+.avatar-preview {
+    display: flex;
+    align-items: center;
+    gap: 1.5rem;
+    margin-bottom: 1.5rem;
+    padding: 1rem;
+    background: #f8f9fa;
+    border-radius: 8px;
+}
+
+.avatar-image {
+    width: 80px;
+    height: 80px;
+    border-radius: 50%;
+    object-fit: cover;
+    border: 3px solid #e0e0e0;
+}
+
+.avatar-url {
+    flex: 1;
+}
+
+.avatar-url input {
+    width: 100%;
+    padding: 0.5rem 0.75rem;
+    border: 1px solid #ced4da;
+    border-radius: 6px;
+}
+
+/* ===== Toggle Switches ===== */
+.toggle-group {
+    display: flex;
+    flex-direction: column;
+    gap: 1rem;
+    margin-bottom: 1.5rem;
+}
+
+.toggle-label {
+    display: flex;
+    align-items: center;
+    gap: 0.75rem;
+    cursor: pointer;
+}
+
+.toggle-input {
+    display: none;
+}
+
+.toggle-switch {
+    position: relative;
+    width: 44px;
+    height: 24px;
+    background: #ccc;
+    border-radius: 12px;
+    transition: background 0.2s;
+    flex-shrink: 0;
+}
+
+.toggle-switch::after {
+    content: "";
+    position: absolute;
+    top: 2px;
+    left: 2px;
+    width: 20px;
+    height: 20px;
+    background: white;
+    border-radius: 50%;
+    transition: transform 0.2s;
+}
+
+.toggle-input:checked + .toggle-switch {
+    background: #0d6efd;
+}
+
+.toggle-input:checked + .toggle-switch::after {
+    transform: translateX(20px);
+}
+
+/* ===== Channels ===== */
+.channels-section {
+    margin-bottom: 1.5rem;
+}
+
+.channels-section h3 {
+    margin-bottom: 0.75rem;
+    font-size: 1.1rem;
+}
+
+.channel-list {
+    display: grid;
+    grid-template-columns: repeat(auto-fill, minmax(150px, 1fr));
+    gap: 0.5rem;
+}
+
+.channel-item {
+    display: flex;
+    align-items: center;
+    gap: 0.5rem;
+    padding: 0.375rem 0.5rem;
+    background: #f8f9fa;
+    border-radius: 4px;
+    cursor: pointer;
+}
+
+/* ===== Security ===== */
+.expandable-panel {
+    border: 1px solid #e0e0e0;
+    border-radius: 8px;
+    margin-bottom: 1.5rem;
+    overflow: hidden;
+}
+
+.panel-header {
+    width: 100%;
+    padding: 1rem 1.25rem;
+    background: #f8f9fa;
+    border: none;
+    cursor: pointer;
+    display: flex;
+    justify-content: space-between;
+    align-items: center;
+    font-size: 1rem;
+    font-weight: 500;
+}
+
+.panel-header:hover {
+    background: #e9ecef;
+}
+
+.panel-body {
+    padding: 1.25rem;
+    border-top: 1px solid #e0e0e0;
+}
+
+.twofa-section {
+    margin-bottom: 1.5rem;
+    padding: 1rem;
+    background: #f8f9fa;
+    border-radius: 8px;
+}
+
+.twofa-row {
+    display: flex;
+    justify-content: space-between;
+    align-items: center;
+}
+
+.twofa-row h3 {
+    margin: 0 0 0.25rem 0;
+    font-size: 1rem;
+}
+
+.status-indicator {
+    font-size: 0.8rem;
+    padding: 0.2rem 0.6rem;
+    border-radius: 12px;
+    font-weight: 500;
+}
+
+.status-enabled {
+    background: #d1e7dd;
+    color: #0f5132;
+}
+
+.status-disabled {
+    background: #f8d7da;
+    color: #842029;
+}
+
+.last-changed {
+    margin-top: 0.5rem;
+    font-size: 0.85rem;
+    color: #666;
+}
+
+/* ===== Sessions Table ===== */
+.sessions-section {
+    margin-top: 1.5rem;
+}
+
+.sessions-section h3 {
+    margin-bottom: 0.75rem;
+}
+
+.sessions-table {
+    width: 100%;
+    border-collapse: collapse;
+    font-size: 0.9rem;
+}
+
+.sessions-table th,
+.sessions-table td {
+    padding: 0.75rem;
+    text-align: left;
+    border-bottom: 1px solid #e0e0e0;
+}
+
+.sessions-table th {
+    background: #f8f9fa;
+    font-weight: 600;
+    color: #555;
+}
+
+.current-session-badge {
+    background: #e7f1ff;
+    color: #0d6efd;
+    padding: 0.2rem 0.5rem;
+    border-radius: 4px;
+    font-size: 0.8rem;
+    font-weight: 500;
+}
+
+.confirm-revoke {
+    display: flex;
+    align-items: center;
+    gap: 0.5rem;
+    font-size: 0.85rem;
+}
+
+/* ===== Appearance ===== */
+.radio-group {
+    display: flex;
+    gap: 1.5rem;
+    margin-top: 0.25rem;
+}
+
+.radio-label {
+    display: flex;
+    align-items: center;
+    gap: 0.375rem;
+    cursor: pointer;
+}
+
+/* ===== Preview Area ===== */
+.preview-area {
+    margin-top: 1.5rem;
+    padding: 1.5rem;
+    border: 2px dashed #ced4da;
+    border-radius: 8px;
+    transition: all 0.3s ease;
+}
+
+.preview-area h4 {
+    margin: 0 0 0.75rem 0;
+    font-size: 1rem;
+}
+
+.preview-card {
+    margin-top: 1rem;
+    padding: 1rem;
+    border-radius: 6px;
+    border: 1px solid #e0e0e0;
+}
+
+.btn-preview {
+    margin-top: 0.5rem;
+}
+
+/* Theme previews */
+.preview-theme-light {
+    background: #ffffff;
+    color: #212529;
+}
+
+.preview-theme-dark {
+    background: #1a1a2e;
+    color: #e0e0e0;
+    border-color: #555;
+}
+
+.preview-theme-dark .preview-card {
+    background: #16213e;
+    border-color: #444;
+}
+
+.preview-theme-system {
+    background: #f0f4f8;
+    color: #333;
+}
+
+/* Font size previews */
+.preview-font-small {
+    font-size: 0.8rem;
+}
+
+.preview-font-medium {
+    font-size: 1rem;
+}
+
+.preview-font-large {
+    font-size: 1.2rem;
+}
+
+/* Compact mode */
+.preview-compact {
+    padding: 0.75rem;
+    line-height: 1.3;
+}
+
+.preview-compact .preview-card {
+    padding: 0.5rem;
+    margin-top: 0.5rem;
+}
+
+/* ===== Loading ===== */
+.loading {
+    color: #666;
+    font-style: italic;
+}
+

